contrast_code <- function(
    contrast
) {

  codes <- c(
    Appendicitis_vs_NIA = "AvN",
    Phenotype_global = "Pg",
    NIA_vs_Mild = "NvM",
    NIA_vs_Severe = "NvS",
    Mild_vs_Severe = "MvS"
  )

  code <- unname(
    codes[
      contrast
    ]
  )

  if (
    length(
      code
    ) != 1L ||
    is.na(
      code
    )
  ) {

    stop(
      "Unknown contrast: ",
      contrast,
      call. = FALSE
    )
  }

  code
}


model_code <- function(
    model
) {

  codes <- c(
    unadjusted = "unadj",
    adjusted_age_sex = "age_sex"
  )

  code <- unname(
    codes[
      model
    ]
  )

  if (
    length(
      code
    ) != 1L ||
    is.na(
      code
    )
  ) {

    stop(
      "Unknown model: ",
      model,
      call. = FALSE
    )
  }

  code
}


method_code <- function(
    method
) {

  codes <- c(
    edgeR_TMM = "edger",
    DESeq2 = "deseq2"
  )

  code <- unname(
    codes[
      method
    ]
  )

  if (
    length(
      code
    ) != 1L ||
    is.na(
      code
    )
  ) {

    stop(
      "Unknown method: ",
      method,
      call. = FALSE
    )
  }

  code
}


