read_rpm_table <- function(
    contrast
) {

  path <- file.path(
    rpm_results_dir,
    "tab",
    paste0(
      contrast_code(
        contrast
      ),
      ".csv"
    )
  )


  if (
    !file.exists(
      path
    )
  ) {

    stop(
      "Missing RPM result table: ",
      path,
      call. = FALSE
    )
  }


  x <- utils::read.csv(
    path,
    stringsAsFactors = FALSE,
    check.names = FALSE
  )


  required <- c(
    "miRNA",
    "p_value",
    "FDR"
  )


  if (
    !all(
      required %in%
        colnames(
          x
        )
    )
  ) {

    stop(
      "Unexpected RPM result structure for ",
      contrast,
      ".",
      call. = FALSE
    )
  }


  effect <- if (
    "log2_median_ratio_group_1_vs_group_2" %in%
      colnames(
        x
      )
  ) {

    as.numeric(
      x$log2_median_ratio_group_1_vs_group_2
    )

  } else if (
    "log2_median_ratio" %in%
      colnames(
        x
      )
  ) {

    as.numeric(
      x$log2_median_ratio
    )

  } else {

    rep(
      NA_real_,
      nrow(
        x
      )
    )
  }


  out <- data.frame(

    miRNA = as.character(
      x$miRNA
    ),

    RPM_effect = effect,

    RPM_p = as.numeric(
      x$p_value
    ),

    RPM_FDR = as.numeric(
      x$FDR
    ),

    RPM_raw = (
      !is.na(
        x$p_value
      ) &
        x$p_value < ALPHA_RAW
    ),

    RPM_FDR_sig = (
      !is.na(
        x$FDR
      ) &
        x$FDR < ALPHA_FDR
    ),

    stringsAsFactors = FALSE
  )


  if (
    nrow(
      out
    ) !=
      nrow(
        rpm_matrix
      ) ||
    !setequal(
      out$miRNA,
      rownames(
        rpm_matrix
      )
    )
  ) {

    stop(
      "RPM result table for ",
      contrast,
      " does not contain exactly the upstream-frozen miRNA feature set.",
      call. = FALSE
    )
  }


  out
}


read_count_table <- function(
    model,
    method,
    contrast,
    suffix
) {

  path <- file.path(
    validation_results_dir,
    model_code(
      model
    ),
    method_code(
      method
    ),
    "tab",
    paste0(
      contrast_code(
        contrast
      ),
      ".csv"
    )
  )


  if (
    !file.exists(
      path
    )
  ) {

    return(
      NULL
    )
  }


  x <- utils::read.csv(
    path,
    stringsAsFactors = FALSE,
    check.names = FALSE
  )


  required <- c(
    "miRNA",
    "p_value",
    "FDR"
  )


  if (
    !all(
      required %in%
        colnames(
          x
        )
    )
  ) {

    stop(
      "Unexpected count-method result structure: ",
      path,
      call. = FALSE
    )
  }


  effect <- if (
    "log2FC" %in%
      colnames(
        x
      )
  ) {

    as.numeric(
      x$log2FC
    )

  } else {

    rep(
      NA_real_,
      nrow(
        x
      )
    )
  }


  out <- data.frame(

    miRNA = as.character(
      x$miRNA
    ),

    effect = effect,

    p = as.numeric(
      x$p_value
    ),

    FDR = as.numeric(
      x$FDR
    ),

    raw = (
      !is.na(
        x$p_value
      ) &
        x$p_value < ALPHA_RAW
    ),

    FDR_sig = (
      !is.na(
        x$FDR
      ) &
        x$FDR < ALPHA_FDR
    ),

    stringsAsFactors = FALSE
  )


  if (
    nrow(
      out
    ) !=
      nrow(
        rpm_matrix
      ) ||
    !setequal(
      out$miRNA,
      rownames(
        rpm_matrix
      )
    )
  ) {

    stop(
      "Count-method result table ",
      path,
      " does not contain exactly the upstream-frozen miRNA feature set.",
      call. = FALSE
    )
  }


  colnames(
    out
  )[
    -1L
  ] <- paste0(
    suffix,
    "_",
    colnames(
      out
    )[
      -1L
    ]
  )


  out
}


# ==============================================================================
# 6. CONCORDANCE HELPERS
# ==============================================================================

same_direction <- function(
    effect_1,
    effect_2,
    global_test = FALSE
) {

  if (
    isTRUE(
      global_test
    )
  ) {

    return(
      rep(
        TRUE,
        length(
          effect_1
        )
      )
    )
  }


  valid <- (
    is.finite(
      effect_1
    ) &
      is.finite(
        effect_2
      ) &
      effect_1 != 0 &
      effect_2 != 0
  )


  out <- rep(
    FALSE,
    length(
      effect_1
    )
  )


  out[
    valid
  ] <- sign(
    effect_1[
      valid
    ]
  ) ==
    sign(
      effect_2[
        valid
      ]
    )


  out
}


same_direction_three <- function(
    effect_1,
    effect_2,
    effect_3,
    global_test = FALSE
) {

  if (
    isTRUE(
      global_test
    )
  ) {

    return(
      rep(
        TRUE,
        length(
          effect_1
        )
      )
    )
  }


  valid <- (
    is.finite(
      effect_1
    ) &
      is.finite(
        effect_2
      ) &
      is.finite(
        effect_3
      ) &
      effect_1 != 0 &
      effect_2 != 0 &
      effect_3 != 0
  )


  out <- rep(
    FALSE,
    length(
      effect_1
    )
  )


  out[
    valid
  ] <- (
    sign(
      effect_1[
        valid
      ]
    ) ==
      sign(
        effect_2[
          valid
        ]
      ) &
      sign(
        effect_2[
          valid
        ]
      ) ==
        sign(
          effect_3[
            valid
          ]
        )
  )


  out
}


collapse_values <- function(
    x
) {

  x <- unique(
    as.character(
      x[
        !is.na(
          x
        ) &
          nzchar(
            as.character(
              x
            )
          )
      ]
    )
  )


  if (
    length(
      x
    ) == 0L
  ) {

    return(
      ""
    )
  }


  paste(
    x,
    collapse = "; "
  )
}


safe_min <- function(
    x
) {

  x <- as.numeric(
    x
  )

  x <- x[
    !is.na(
      x
    ) &
      is.finite(
        x
      )
  ]


  if (
    length(
      x
    ) == 0L
  ) {

    return(
      NA_real_
    )
  }


  min(
    x
  )
}


