    suffix = "edgeR"
  )


  DESeq2_unadjusted <- read_count_table(
    model = "unadjusted",
    method = "DESeq2",
    contrast = contrast,
    suffix = "DESeq2"
  )


  if (
    is.null(
      edgeR_unadjusted
    ) ||
    is.null(
      DESeq2_unadjusted
    )
  ) {

    stop(
      "Missing primary unadjusted edgeR or DESeq2 results for ",
      contrast,
      ".",
      call. = FALSE
    )
  }


  integrated <- rpm_tab |>
    dplyr::left_join(
      edgeR_unadjusted,
      by = "miRNA"
    ) |>
    dplyr::left_join(
      DESeq2_unadjusted,
      by = "miRNA"
    )


  integrated$count_direction_concordant_unadjusted <- same_direction(
    integrated$edgeR_effect,
    integrated$DESeq2_effect,
    global_test = spec$global_test
  )


  integrated$all_three_direction_concordant <- same_direction_three(
    integrated$RPM_effect,
    integrated$edgeR_effect,
    integrated$DESeq2_effect,
    global_test = spec$global_test
  )


  integrated$count_nominal_both_unadjusted <- (
    integrated$edgeR_raw &
      integrated$DESeq2_raw &
      integrated$count_direction_concordant_unadjusted
  )


  integrated$all_three_nominal_unadjusted <- (
    integrated$RPM_raw &
      integrated$edgeR_raw &
      integrated$DESeq2_raw &
      integrated$all_three_direction_concordant
  )


  integrated$count_FDR_both_unadjusted <- (
    integrated$edgeR_FDR_sig &
      integrated$DESeq2_FDR_sig &
      integrated$count_direction_concordant_unadjusted
  )


  integrated$count_FDR_cross_supported_unadjusted <- (
    (
      integrated$edgeR_FDR_sig &
        integrated$DESeq2_raw
    ) |
      (
        integrated$DESeq2_FDR_sig &
          integrated$edgeR_raw
      )
  ) &
    integrated$count_direction_concordant_unadjusted


  integrated$count_any_FDR_unadjusted <- (
    integrated$edgeR_FDR_sig |
      integrated$DESeq2_FDR_sig
  )


  integrated$RPM_supports_count_FDR_unadjusted <- (
    integrated$RPM_raw &
      integrated$count_FDR_cross_supported_unadjusted &
      integrated$all_three_direction_concordant
  )


  # ---------------------------------------------------------------------------
  # Age + sex sensitivity
  # ---------------------------------------------------------------------------

  if (
    adjusted_available
  ) {

    edgeR_adjusted <- read_count_table(
      model = "adjusted_age_sex",
      method = "edgeR_TMM",
      contrast = contrast,
      suffix = "edgeR_adjusted"
    )


    DESeq2_adjusted <- read_count_table(
      model = "adjusted_age_sex",
      method = "DESeq2",
      contrast = contrast,
      suffix = "DESeq2_adjusted"
    )

  } else {

    edgeR_adjusted <- NULL
    DESeq2_adjusted <- NULL
  }


  if (
    !is.null(
      edgeR_adjusted
    ) &&
    !is.null(
      DESeq2_adjusted
    )
  ) {

    integrated <- integrated |>
      dplyr::left_join(
        edgeR_adjusted,
        by = "miRNA"
      ) |>
      dplyr::left_join(
        DESeq2_adjusted,
        by = "miRNA"
      )


    integrated$count_direction_concordant_adjusted <- same_direction(
      integrated$edgeR_adjusted_effect,
      integrated$DESeq2_adjusted_effect,
      global_test = spec$global_test
    )


    integrated$count_nominal_both_adjusted <- (
      integrated$edgeR_adjusted_raw &
        integrated$DESeq2_adjusted_raw &
        integrated$count_direction_concordant_adjusted
    )


    integrated$count_FDR_both_adjusted <- (
      integrated$edgeR_adjusted_FDR_sig &
        integrated$DESeq2_adjusted_FDR_sig &
        integrated$count_direction_concordant_adjusted
    )


    integrated$count_FDR_cross_supported_adjusted <- (
      (
        integrated$edgeR_adjusted_FDR_sig &
          integrated$DESeq2_adjusted_raw
      ) |
        (
          integrated$DESeq2_adjusted_FDR_sig &
            integrated$edgeR_adjusted_raw
        )
    ) &
      integrated$count_direction_concordant_adjusted


    integrated$count_any_FDR_adjusted <- (
      integrated$edgeR_adjusted_FDR_sig |
        integrated$DESeq2_adjusted_FDR_sig
    )


    integrated$edgeR_direction_stable_after_adjustment <- same_direction(
      integrated$edgeR_effect,
      integrated$edgeR_adjusted_effect,
      global_test = spec$global_test
    )


    integrated$DESeq2_direction_stable_after_adjustment <- same_direction(
      integrated$DESeq2_effect,
      integrated$DESeq2_adjusted_effect,
      global_test = spec$global_test
    )

  } else {

    integrated$edgeR_adjusted_effect <- NA_real_
    integrated$edgeR_adjusted_p <- NA_real_
    integrated$edgeR_adjusted_FDR <- NA_real_
    integrated$edgeR_adjusted_raw <- FALSE
    integrated$edgeR_adjusted_FDR_sig <- FALSE

    integrated$DESeq2_adjusted_effect <- NA_real_
    integrated$DESeq2_adjusted_p <- NA_real_
    integrated$DESeq2_adjusted_FDR <- NA_real_
    integrated$DESeq2_adjusted_raw <- FALSE
    integrated$DESeq2_adjusted_FDR_sig <- FALSE

    integrated$count_direction_concordant_adjusted <- FALSE
    integrated$count_nominal_both_adjusted <- FALSE
    integrated$count_FDR_both_adjusted <- FALSE
    integrated$count_FDR_cross_supported_adjusted <- FALSE
    integrated$count_any_FDR_adjusted <- FALSE
    integrated$edgeR_direction_stable_after_adjustment <- FALSE
    integrated$DESeq2_direction_stable_after_adjustment <- FALSE
  }


  integrated$FDR_concordant_robust_same_contrast <- (
    integrated$count_FDR_both_unadjusted &
      integrated$count_FDR_both_adjusted
  )


  integrated$FDR_cross_supported_robust_same_contrast <- (
    integrated$count_FDR_cross_supported_unadjusted &
      integrated$count_FDR_cross_supported_adjusted
  )


  integrated$nominal_count_robust_same_contrast <- (
    integrated$count_nominal_both_unadjusted &
      integrated$count_nominal_both_adjusted
  )


  integrated$contrast <- contrast
  integrated$global_test <- spec$global_test

  integrated$positive_effect_definition <- if (
    isTRUE(
      spec$global_test
    )
  ) {

    "Omnibus test; no unique effect direction"

  } else {

    paste0(
      "Positive effect = higher in ",
      spec$positive_group,
      " than ",
      spec$negative_group
    )
  }


  integrated <- integrated |>
    dplyr::arrange(
      dplyr::desc(
        FDR_concordant_robust_same_contrast
      ),
      dplyr::desc(
        count_FDR_both_unadjusted
      ),
      dplyr::desc(
        count_FDR_cross_supported_unadjusted
      ),
      dplyr::desc(
        all_three_nominal_unadjusted
      ),
      dplyr::desc(
        count_nominal_both_unadjusted
      ),
      edgeR_FDR,
      DESeq2_FDR,
      RPM_FDR
    )


  utils::write.csv(
    integrated,
    prepare_output_file(
      file.path(
        integrated_results_dir,
        paste0(
          contrast,
          "_integrated_results.csv"
        )
      )
    ),
    row.names = FALSE
  )


  integrated_tables[[
    contrast
  ]] <- integrated
}


