      ),

      n_edgeR_nominal = sum(
        edgeR_raw,
        na.rm = TRUE
      ),

      n_DESeq2_nominal = sum(
        DESeq2_raw,
        na.rm = TRUE
      ),

      n_count_nominal_both = sum(
        count_nominal_both_unadjusted,
        na.rm = TRUE
      ),

      n_all_three_nominal = sum(
        all_three_nominal_unadjusted,
        na.rm = TRUE
      ),

      n_count_FDR_any = sum(
        count_any_FDR_unadjusted,
        na.rm = TRUE
      ),

      n_count_FDR_cross_supported = sum(
        count_FDR_cross_supported_unadjusted,
        na.rm = TRUE
      ),

      n_count_FDR_both = sum(
        count_FDR_both_unadjusted,
        na.rm = TRUE
      ),

      n_RPM_supports_count_FDR = sum(
        RPM_supports_count_FDR_unadjusted,
        na.rm = TRUE
      ),

      n_adjusted_count_nominal_both = sum(
        count_nominal_both_adjusted,
        na.rm = TRUE
      ),

      n_adjusted_count_FDR_cross_supported = sum(
        count_FDR_cross_supported_adjusted,
        na.rm = TRUE
      ),

      n_adjusted_count_FDR_both = sum(
        count_FDR_both_adjusted,
        na.rm = TRUE
      ),

      n_FDR_concordant_robust_same_contrast = sum(
        FDR_concordant_robust_same_contrast,
        na.rm = TRUE
      ),

      n_FDR_cross_supported_robust_same_contrast = sum(
        FDR_cross_supported_robust_same_contrast,
        na.rm = TRUE
      ),

      n_nominal_count_robust_same_contrast = sum(
        nominal_count_robust_same_contrast,
        na.rm = TRUE
      ),

      minimum_RPM_p = safe_min(
        RPM_p
      ),

      minimum_RPM_FDR = safe_min(
        RPM_FDR
      ),

      minimum_edgeR_p = safe_min(
        edgeR_p
      ),

      minimum_edgeR_FDR = safe_min(
        edgeR_FDR
      ),

      minimum_DESeq2_p = safe_min(
        DESeq2_p
      ),

      minimum_DESeq2_FDR = safe_min(
        DESeq2_FDR
      ),

      minimum_edgeR_adjusted_FDR = safe_min(
        edgeR_adjusted_FDR
      ),

      minimum_DESeq2_adjusted_FDR = safe_min(
        DESeq2_adjusted_FDR
      ),

      RPM_nominal_analyses = collapse_values(
        contrast[
          RPM_raw %in%
            TRUE
        ]
      ),

      count_nominal_concordant_analyses = collapse_values(
        contrast[
          count_nominal_both_unadjusted %in%
            TRUE
