# ==============================================================================
# 10.1 Evidence class
# ==============================================================================

add_evidence_class <- function(
    summary_table
) {

  summary_table$any_primary_nominal_signal <- (
    summary_table$n_RPM_nominal > 0L |
      summary_table$n_edgeR_nominal > 0L |
      summary_table$n_DESeq2_nominal > 0L
  )


  summary_table$evidence_class <- dplyr::case_when(

    summary_table$n_FDR_concordant_robust_same_contrast > 0L ~
      "FDR_concordant_robust",

    summary_table$n_FDR_cross_supported_robust_same_contrast > 0L ~
      "FDR_cross_supported_robust",

    summary_table$n_count_FDR_both > 0L ~
      "FDR_concordant_primary",

    summary_table$n_count_FDR_cross_supported > 0L ~
      "FDR_cross_supported_primary",

    summary_table$n_count_FDR_any > 0L ~
      "FDR_single_count_method",

    summary_table$n_all_three_nominal > 0L ~
      "All_three_nominal_concordant",

    summary_table$n_count_nominal_both > 0L ~
      "Count_methods_nominal_concordant",

    summary_table$any_primary_nominal_signal ~
      "Other_nominal_signal",

    TRUE ~
      "No_integrated_signal"
  )


  evidence_order <- c(
    "FDR_concordant_robust",
    "FDR_cross_supported_robust",
    "FDR_concordant_primary",
    "FDR_cross_supported_primary",
    "FDR_single_count_method",
    "All_three_nominal_concordant",
    "Count_methods_nominal_concordant",
    "Other_nominal_signal",
    "No_integrated_signal"
  )


  summary_table$evidence_class <- factor(
    summary_table$evidence_class,
    levels = evidence_order
  )


  summary_table <- summary_table |>
    dplyr::arrange(
      evidence_class,
      dplyr::desc(
        n_FDR_concordant_robust_same_contrast
      ),
      dplyr::desc(
        n_count_FDR_both
      ),
      dplyr::desc(
        n_count_FDR_cross_supported
      ),
      dplyr::desc(
        n_all_three_nominal
      ),
      dplyr::desc(
        n_count_nominal_both
      ),
      minimum_edgeR_FDR,
      minimum_DESeq2_FDR,
      minimum_RPM_p
    )


  summary_table$evidence_class <- as.character(
    summary_table$evidence_class
  )


  summary_table
}


