# ==============================================================================
# 11. FINAL DOWNSTREAM CANDIDATE HIERARCHY
# ==============================================================================

# Script 06 is the single source of truth for the miRNAs carried forward into
# downstream clinical and in-silico analyses.
#
# The hierarchy is derived from the integrated evidence classes:
#
#   Primary_robust
#       FDR_concordant_robust
#       FDR_cross_supported_robust
#
#   Secondary_integrated
#       All_three_nominal_concordant
#
# All remaining miRNAs stay in the complete integrated evidence tables but are
# not carried forward into targeted downstream analyses.

candidate_priority_all <- candidate_summary_all |>
  dplyr::mutate(
    downstream_category = dplyr::case_when(
      evidence_class %in% c(
        "FDR_concordant_robust",
        "FDR_cross_supported_robust"
      ) ~ "Primary_robust",

      evidence_class ==
        "All_three_nominal_concordant" ~
        "Secondary_integrated",

      TRUE ~
        "Exploratory_not_carried_forward"
    ),
    best_evidence_class = evidence_class
  )


downstream_candidate_priority <- candidate_priority_all |>
  dplyr::filter(
    downstream_category %in% c(
      "Primary_robust",
      "Secondary_integrated"
    )
  ) |>
  dplyr::mutate(
    downstream_rank = dplyr::row_number()
  )


candidate_hierarchy_summary <- candidate_priority_all |>
  dplyr::count(
    downstream_category,
    name = "n_miRNAs"
  )


if (
  anyDuplicated(
    downstream_candidate_priority$miRNA
  ) > 0L
) {
  stop(
    "Duplicated miRNAs detected in the downstream candidate hierarchy.",
    call. = FALSE
  )
}


