log2_rpm <- log2(
  rpm_matrix +
    1
)


save_integrated_heatmap <- function(
    selected_miRNAs,
    set_code,
    set_label
) {

  selected_miRNAs <- intersect(
    unique(
      selected_miRNAs
    ),
    rownames(
      log2_rpm
    )
  )


  if (
    length(
      selected_miRNAs
    ) == 0L
  ) {

    message(
      "Integrated heatmap skipped for ",
      set_label,
      ": no miRNAs."
    )

    return(
      invisible(
        NULL
      )
    )
  }


  plot_metadata <- metadata |>
    dplyr::arrange(
      Phenotype,
      Sample
    )


  ordered_samples <- plot_metadata$Sample


  matrix_selected <- log2_rpm[
    selected_miRNAs,
    ordered_samples,
    drop = FALSE
  ]


  z_matrix <- t(
    scale(
      t(
        matrix_selected
      )
    )
  )


  z_matrix[
    !is.finite(
      z_matrix
    )
  ] <- 0


  annotation <- ComplexHeatmap::HeatmapAnnotation(
    Phenotype = plot_metadata$Phenotype,
    annotation_name_side = "left"
  )


  heatmap_object <- ComplexHeatmap::Heatmap(

    z_matrix,

    name = "Row Z-score",

    col = circlize::colorRamp2(
      c(
        -2,
        0,
        2
      ),
      c(
        "navy",
        "white",
        "firebrick3"
      )
    ),

    top_annotation = annotation,

    column_split = plot_metadata$Phenotype,

    cluster_rows = length(
      selected_miRNAs
    ) > 1L,

    cluster_columns = FALSE,

    show_column_names = FALSE,

    show_row_names = TRUE,

    row_names_gp = grid::gpar(
      fontsize = if (
        length(
          selected_miRNAs
        ) > 35L
      ) {
        6.5
      } else {
        8
      }
    ),

    column_title = paste0(
      set_label,
      " (",
      length(
        selected_miRNAs
      ),
      " miRNAs)"
    ),

    use_raster = FALSE
  )


  output_dir <- file.path(
    heatmap_dir,
    set_code
  )


  ensure_dir(
    output_dir
  )


  figure_height <- max(
    5,
    min(
      12,
      0.20 *
        length(
          selected_miRNAs
        ) +
        3.5
    )
  )


  draw_heatmap <- function() {

    ComplexHeatmap::draw(
      heatmap_object,
      heatmap_legend_side = "right",
      annotation_legend_side = "right"
    )
  }


  draw_to_pdf(
    filename = file.path(
      output_dir,
      paste0(
        set_code,
        "_heatmap.pdf"
      )
    ),
    width = 8,
    height = figure_height,
    draw = draw_heatmap
  )


  draw_to_tiff(
    filename = file.path(
      output_dir,
      paste0(
        set_code,
        "_heatmap.tiff"
      )
    ),
    width = 8,
    height = figure_height,
    units = "in",
    res = 600,
    compression = "lzw",
    draw = draw_heatmap
  )


  utils::write.csv(
    data.frame(
      candidate_set = set_code,
      definition = set_label,
      miRNA = selected_miRNAs,
      stringsAsFactors = FALSE
    ),
    prepare_output_file(
      file.path(
        output_dir,
        paste0(
          set_code,
          "_miRNAs.csv"
        )
      )
    ),
    row.names = FALSE
  )


  invisible(
    heatmap_object
  )
}


save_integrated_pca <- function(
    selected_miRNAs,
    set_code,
    set_label
) {

  selected_miRNAs <- intersect(
    unique(
      selected_miRNAs
    ),
    rownames(
      log2_rpm
    )
  )


  if (
    length(
      selected_miRNAs
    ) < 2L
  ) {

    message(
      "Integrated PCA skipped for ",
      set_label,
      ": fewer than two miRNAs."
    )

    return(
      invisible(
        NULL
      )
    )
  }


  pca_matrix <- log2_rpm[
    selected_miRNAs,
    metadata$Sample,
    drop = FALSE
  ]


  feature_sd <- apply(
    pca_matrix,
    1L,
    stats::sd
  )


  pca_matrix <- pca_matrix[
    is.finite(
      feature_sd
    ) &
      feature_sd > 0,
    ,
    drop = FALSE
  ]


  if (
    nrow(
      pca_matrix
    ) < 2L
  ) {

    return(
      invisible(
        NULL
      )
    )
  }


  pca <- stats::prcomp(
    t(
      pca_matrix
    ),
    center = TRUE,
    scale. = TRUE
  )


  variance <- (
    pca$sdev^2
  ) /
    sum(
      pca$sdev^2
    )


  pca_df <- data.frame(

    Sample = rownames(
      pca$x
    ),

    PC1 = pca$x[
      ,
      1L
    ],

    PC2 = pca$x[
      ,
      2L
    ],

    stringsAsFactors = FALSE
  )


  if (
    ncol(
      pca$x
    ) >= 3L
  ) {

    pca_df$PC3 <- pca$x[
      ,
      3L
    ]
  }


  pca_df <- dplyr::left_join(
    pca_df,
    metadata[
      ,
      c(
        "Sample",
        "Phenotype",
        "Phenotype_full",
        "Appendicitis_status",
        "Age",
        "Sex"
      ),
      drop = FALSE
    ],
    by = "Sample"
  )


  group_counts <- table(
    pca_df$Phenotype
  )


  eligible_groups <- names(
    group_counts[
      group_counts >= 3L
    ]
  )


  ellipse_data <- pca_df[
    as.character(
      pca_df$Phenotype
    ) %in%
      eligible_groups,
    ,
    drop = FALSE
  ]


  plot_object <- ggplot2::ggplot(
    pca_df,
    ggplot2::aes(
      x = PC1,
      y = PC2,
      color = Phenotype
    )
  )


  if (
    nrow(
      ellipse_data
    ) > 0L
  ) {

    plot_object <- plot_object +
      ggplot2::stat_ellipse(
        data = ellipse_data,
        ggplot2::aes(
          fill = Phenotype
        ),
        geom = "polygon",
        type = "norm",
        level = 0.95,
        alpha = 0.12,
        color = NA,
        show.legend = FALSE
      ) +
      ggplot2::stat_ellipse(
        data = ellipse_data,
        type = "norm",
        level = 0.95,
        linewidth = 0.6,
        alpha = 0.85,
        show.legend = FALSE
      )
  }


  plot_object <- plot_object +
    ggplot2::geom_point(
      size = 3,
      alpha = 0.95
    ) +
    ggplot2::labs(
      title = paste0(
        set_label,
        " — exploratory PCA"
      ),
      subtitle = paste0(
        nrow(
          pca_matrix
        ),
        " miRNAs; integrated post-selection visualization"
      ),
      x = sprintf(
        "PC1 (%.1f%%)",
        100 *
          variance[1L]
      ),
      y = sprintf(
        "PC2 (%.1f%%)",
        100 *
          variance[2L]
      ),
      color = NULL
    ) +
    ggplot2::theme_classic(
      base_size = 11
    ) +
    ggplot2::theme(
      plot.title = ggplot2::element_text(
        face = "bold"
      ),
      legend.position = "right"
    )


  output_dir <- file.path(
    pca_dir,
    set_code
  )


  ensure_dir(
    output_dir
  )


  save_ggplot_pdf(
    plot = plot_object,
    filename = file.path(
      output_dir,
      paste0(
        set_code,
        "_PCA_PC1_PC2.pdf"
      )
    ),
    width = 7,
    height = 5
  )


  save_ggplot_tiff(
    plot = plot_object,
    filename = file.path(
      output_dir,
      paste0(
        set_code,
        "_PCA_PC1_PC2.tiff"
      )
    ),
    width = 7,
    height = 5,
    dpi = 600
  )


  utils::write.csv(
    pca_df,
    prepare_output_file(
      file.path(
        output_dir,
        paste0(
          set_code,
          "_PCA_coordinates.csv"
        )
      )
    ),
    row.names = FALSE
  )


  utils::write.csv(
    data.frame(
      PC = paste0(
        "PC",
        seq_along(
          variance
        )
      ),
      variance_explained_pct = 100 *
        variance,
      cumulative_variance_explained_pct = 100 *
        cumsum(
          variance
        ),
      stringsAsFactors = FALSE
    ),
    prepare_output_file(
      file.path(
        output_dir,
        paste0(
          set_code,
          "_PCA_variance.csv"
        )
      )
    ),
    row.names = FALSE
  )


  invisible(
    list(
      pca = pca,
      coordinates = pca_df,
      variance = variance,
      plot = plot_object
    )
  )
}


save_integrated_visual_pair <- function(
    selected_miRNAs,
    set_code,
    set_label
) {

  heatmap_object <- save_integrated_heatmap(
    selected_miRNAs = selected_miRNAs,
    set_code = set_code,
    set_label = set_label
  )


  pca_object <- save_integrated_pca(
    selected_miRNAs = selected_miRNAs,
    set_code = set_code,
    set_label = set_label
  )


  invisible(
    list(
      heatmap = heatmap_object,
      pca = pca_object
    )
  )
}


